/**
 * FILE: concept_2_financial_alchemy_lab.js
 * THEME: Finance & Investment — Financial Alchemy & Liquid Asset Growth Lab
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Harmonic phase multiples for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;
  const p6 = sceneProgress * tau * 6;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#182238',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    rackBody: '#E2E8F0',
    rackShade: '#94A3B8',
    standBlue: '#2980B9',
    standBlueDark: '#1B5E8A',
    standBlueLight: '#5DADE2',
    glassTint: '#F8FAFC',
    glassHighlight: '#FFFFFF',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    cyanLight: '#A5F3FC',
    cyanMid: '#38BDF8',
    cyanDark: '#0284C7',
    purpleLight: '#DDD6FE',
    purpleMid: '#A855F7',
    purpleDark: '#7E22CE',
    orangeLight: '#FED7AA',
    orangeMid: '#FB923C',
    orangeDark: '#EA580C',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#34D399',
    emeraldDark: '#059669',
    coralRed: '#F87171',
    slateDark: '#334155',
    slateMid: '#64748B'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Sign
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Clipped Dual-Layer Wave Liquid Fill
  function drawClippedWaveLiquid(clipPathFn, leftX, rightX, surfaceY, bottomY, backColor, frontColor, waveAmp, waveFreq, phase, outlineColor, lineW) {
    ctx.save();
    clipPathFn();
    ctx.clip();

    const widthSpan = rightX - leftX;
    const steps = 28;

    // Back wave layer
    ctx.beginPath();
    ctx.moveTo(leftX - 10 * s, bottomY + 20 * s);
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const wx = leftX + u * widthSpan;
      const wy = surfaceY - 4 * s + Math.sin(u * waveFreq * Math.PI - phase + 1.1) * (waveAmp * 0.75);
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(rightX + 10 * s, bottomY + 20 * s);
    ctx.closePath();
    ctx.fillStyle = backColor;
    ctx.fill();

    // Front wave layer
    ctx.beginPath();
    ctx.moveTo(leftX - 10 * s, bottomY + 20 * s);
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const wx = leftX + u * widthSpan;
      const wy = surfaceY + Math.sin(u * waveFreq * Math.PI + phase) * waveAmp;
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(rightX + 10 * s, bottomY + 20 * s);
    ctx.closePath();
    ctx.fillStyle = frontColor;
    ctx.fill();

    // Crisp top meniscus line
    if (outlineColor && lineW > 0) {
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const u = i / steps;
        const wx = leftX + u * widthSpan;
        const wy = surfaceY + Math.sin(u * waveFreq * Math.PI + phase) * waveAmp;
        if (i === 0) ctx.moveTo(wx, wy);
        else ctx.lineTo(wx, wy);
      }
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineW;
      ctx.stroke();
    }

    ctx.restore();
  }

  // =========================================================================
  // 2. LABORATORY BASELINE PLATFORM & NON-INTERSECTING PIPELINES
  // =========================================================================
  const baseLineY = cy + 390 * s;

  // Main Ground Line
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 730 * s, baseLineY);
  ctx.lineTo(cx + 730 * s, baseLineY);
  ctx.stroke();

  // Outer baseline dashes (animated horizontal breathing within safe margins)
  const dashShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 805 * s - dashShift, baseLineY);
  ctx.lineTo(cx - 755 * s - dashShift, baseLineY);
  ctx.moveTo(cx + 755 * s + dashShift, baseLineY);
  ctx.lineTo(cx + 805 * s + dashShift, baseLineY);
  ctx.stroke();

  // Secondary sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 380 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 380 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Non-Intersecting Horizontal Telemetry Connectors between Zones (y = cy - 230*s)
  // Left gap: [cx - 275*s, cx - 205*s] | Right gap: [cx + 205*s, cx + 275*s]
  const connY = cy - 230 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 268 * s, connY);
  ctx.lineTo(cx - 212 * s, connY);
  ctx.moveTo(cx + 212 * s, connY);
  ctx.lineTo(cx + 268 * s, connY);
  ctx.stroke();

  // Traveling node along Left & Right Connectors
  const connProgL = (sceneProgress * 4) % 1;
  const connXL = cx - 260 * s + connProgL * 40 * s;
  ctx.beginPath();
  ctx.arc(connXL, connY, 6 * s, 0, tau);
  fillAndStroke(COL.cyanMid, COL.outline, 2.5 * s);

  const connProgR = (sceneProgress * 4 + 0.5) % 1;
  const connXR = cx + 220 * s + connProgR * 40 * s;
  ctx.beginPath();
  ctx.arc(connXR, connY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT ZONE (TOP): PORTFOLIO ALLOCATION TELEMETRY CARD
  // Bounding Box: x in [cx - 680*s, cx - 275*s], y in [cy - 365*s, cy - 125*s]
  // Strictly separated from Test Tube Rack below by 75*s vertical gap!
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const cardLX = cx - 680 * s;
  const cardLY = cy - 360 * s + ltFloatY;
  const cardLW = 405 * s;
  const cardLH = 215 * s;

  roundedRectPath(cardLX, cardLY, cardLW, cardLH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left Card
  roundedRectPath(cardLX + 16 * s, cardLY + 16 * s, cardLW - 32 * s, 38 * s, 10 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // 3 status dots on left of header strip
  const dotColors = [COL.cyanMid, COL.purpleMid, COL.orangeMid];
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(cardLX + 38 * s + d * 22 * s, cardLY + 35 * s, 6.5 * s, 0, tau);
    fillAndStroke(dotColors[d], COL.outline, 2.5 * s);
  }

  // Header label bar
  roundedRectPath(cardLX + 115 * s, cardLY + 29 * s, 160 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  // Left Sub-Box: Animated Multi-Segment Portfolio Donut Wheel
  const wheelCX = cardLX + 82 * s;
  const wheelCY = cardLY + 134 * s;
  const wheelR = 48 * s;
  const wheelRot = p1;

  const segAngles = [0, tau * 0.42, tau * 0.74, tau];
  const segCols = [COL.cyanMid, COL.purpleMid, COL.orangeMid];

  for (let sg = 0; sg < 3; sg++) {
    ctx.beginPath();
    ctx.moveTo(wheelCX, wheelCY);
    ctx.arc(wheelCX, wheelCY, wheelR, wheelRot + segAngles[sg], wheelRot + segAngles[sg + 1]);
    ctx.closePath();
    fillAndStroke(segCols[sg], COL.outline, thinStrokeW);
  }

  // Inner Donut Hole
  ctx.beginPath();
  ctx.arc(wheelCX, wheelCY, 22 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right Sub-Box: 3 Synchronized Asset Allocation Bars (matching the 3 test tubes below)
  const barStartX = cardLX + 156 * s;
  const barTrackW = 225 * s;
  for (let b = 0; b < 3; b++) {
    const by = cardLY + 78 * s + b * 44 * s;

    // Label pill above bar
    roundedRectPath(barStartX, by, 75 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    // Progress bar track
    roundedRectPath(barStartX, by + 15 * s, barTrackW, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    // Animated fill synchronized with corresponding test tube wave
    const tubeFillNorm = 0.58 + 0.24 * Math.sin(p2 + b * 1.15);
    roundedRectPath(barStartX + 3 * s, by + 18 * s, (barTrackW - 6 * s) * tubeFillNorm, 12 * s, 6 * s);
    fillAndStroke(segCols[b], null, 0);
  }

  // =========================================================================
  // 4. LEFT ZONE (BOTTOM): ASSET DIVERSIFICATION TEST TUBE RACK
  // Bounding Box: x in [cx - 680*s, cx - 275*s], y in [cy - 55*s, cy + 390*s]
  // Inspired directly by the 3-tube rack on the left of the reference video
  // =========================================================================
  const rackLeftX = cx - 675 * s;
  const rackWidth = 396 * s;
  const rackRightX = rackLeftX + rackWidth;
  const collarY = cy + 72 * s;
  const collarH = 26 * s;
  const baseRackH = 28 * s;
  const baseRackY = baseLineY - baseRackH;

  // 4A. Left & Right Rack Support Pillars (Positioned outside the 3 tubes so they never intersect)
  const pillarW = 22 * s;
  roundedRectPath(rackLeftX + 14 * s, collarY + collarH - 2 * s, pillarW, baseRackY - (collarY + collarH) + 4 * s, 4 * s);
  fillAndStroke(COL.rackBody, COL.outline, strokeW);

  roundedRectPath(rackRightX - 14 * s - pillarW, collarY + collarH - 2 * s, pillarW, baseRackY - (collarY + collarH) + 4 * s, 4 * s);
  fillAndStroke(COL.rackBody, COL.outline, strokeW);

  // 4B. Three Glass Test Tubes (Strictly spaced with 42*s clear gap between tubes)
  // Tube Centers: cx - 585*s, cx - 477*s, cx - 369*s | Tube Width = 64*s
  const tubeCenters = [cx - 585 * s, cx - 477 * s, cx - 369 * s];
  const tubeW = 64 * s;
  const tubeTopY = cy - 42 * s;
  const tubeBotY = baseRackY + 4 * s;
  const tubeH = tubeBotY - tubeTopY;
  const tubeR = tubeW * 0.5;

  const tubeThemes = [
    { back: COL.cyanDark, front: COL.cyanMid, light: COL.cyanLight, phase: 0.0, baseLvl: 0.52 },
    { back: COL.purpleDark, front: COL.purpleMid, light: COL.purpleLight, phase: 1.15, baseLvl: 0.45 },
    { back: COL.orangeDark, front: COL.orangeMid, light: COL.orangeLight, phase: 2.30, baseLvl: 0.58 }
  ];

  for (let i = 0; i < 3; i++) {
    const tcx = tubeCenters[i];
    const tx = tcx - tubeR;
    const thm = tubeThemes[i];

    // Define U-shaped Test Tube Path
    const defineTubePath = function () {
      ctx.beginPath();
      ctx.moveTo(tx, tubeTopY + 12 * s);
      ctx.lineTo(tx, tubeBotY - tubeR);
      ctx.arc(tcx, tubeBotY - tubeR, tubeR, Math.PI, 0, true);
      ctx.lineTo(tx + tubeW, tubeTopY + 12 * s);
      ctx.closePath();
    };

    // Tube Glass Back Fill
    defineTubePath();
    fillAndStroke(COL.glassTint, null, 0);

    // Animated Liquid Level inside Tube (Oscillates smoothly within safe tube bounds)
    const lvlOsc = Math.sin(p2 + thm.phase) * 28 * s;
    const surfY = tubeTopY + tubeH * thm.baseLvl + lvlOsc;

    drawClippedWaveLiquid(
      defineTubePath,
      tx,
      tx + tubeW,
      surfY,
      tubeBotY,
      thm.back,
      thm.front,
      5.5 * s,
      1.5,
      p4 + thm.phase,
      COL.outline,
      3 * s
    );

    // Rising Micro-Bubbles inside Tube Liquid (Strictly clipped & below surface)
    ctx.save();
    defineTubePath();
    ctx.clip();
    for (let b = 0; b < 2; b++) {
      const bProg = (sceneProgress * 3 + i * 0.33 + b * 0.5) % 1;
      const bStartY = tubeBotY - tubeR - 8 * s;
      const bEndY = surfY + 18 * s;
      if (bEndY < bStartY) {
        const by = bStartY - bProg * (bStartY - bEndY);
        const bx = tcx + (b === 0 ? -10 * s : 11 * s) + Math.sin(p4 + b * 2 + i) * 3 * s;
        const br = (4.5 + b * 1.5) * s * Math.sin(bProg * Math.PI);
        if (br > 0.8 * s) {
          ctx.beginPath();
          ctx.arc(bx, by, br, 0, tau);
          fillAndStroke(thm.light, COL.outline, 2 * s);
        }
      }
    }

    // Crisp Vertical Glass Specular Highlight Strip on Left Inside of Tube
    roundedRectPath(tx + 9 * s, tubeTopY + 26 * s, 7 * s, tubeH - 72 * s, 3.5 * s);
    fillAndStroke('rgba(255, 255, 255, 0.65)', null, 0);
    ctx.restore();

    // Tube Outer Bold Outline
    defineTubePath();
    fillAndStroke(null, COL.outline, strokeW);

    // Tube Top Flanged Rim Lip (Width = 78*s, still leaves 30*s gap between adjacent rims!)
    const rimW = 78 * s;
    roundedRectPath(tcx - rimW * 0.5, tubeTopY, rimW, 14 * s, 7 * s);
    fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);
  }

  // 4C. Test Tube Rack Upper Collar Bar & Lower Base Bar (Drawn over tube bodies for authentic rack depth)
  roundedRectPath(rackLeftX, collarY, rackWidth, collarH, 10 * s);
  fillAndStroke(COL.rackBody, COL.outline, strokeW);

  // Subtle flat shade strip at bottom of upper collar
  roundedRectPath(rackLeftX + 6 * s, collarY + collarH - 9 * s, rackWidth - 12 * s, 6 * s, 3 * s);
  fillAndStroke(COL.rackShade, null, 0);

  // Lower Rack Base sitting flush on baseLineY
  roundedRectPath(rackLeftX, baseRackY, rackWidth, baseRackH, 10 * s);
  fillAndStroke(COL.rackBody, COL.outline, strokeW);

  // =========================================================================
  // 5. CENTER ZONE: GOLD LIQUIDITY ERLENMEYER FLASK, STAND & BURNER
  // Bounding Box: x in [cx - 210*s, cx + 210*s], y in [cy - 380*s, cy + 390*s]
  // Directly inspired by the central Erlenmeyer flask & blue stand in reference video
  // =========================================================================
  const flaskCX = cx - 22 * s;
  const standBaseX = cx - 195 * s;
  const standBaseW = 390 * s;
  const standBaseH = 54 * s;
  const standBaseY = baseLineY - standBaseH;

  // 5A. Vertical Metal Stand Rod & Clamp Arm (Positioned on right at cx + 150*s)
  const rodCX = cx + 150 * s;
  const rodW = 22 * s;
  const rodTopY = cy - 235 * s;
  const clampY = cy - 172 * s;
  const clampH = 22 * s;

  // Vertical Rod
  roundedRectPath(rodCX - rodW * 0.5, rodTopY, rodW, standBaseY - rodTopY + 6 * s, 10 * s);
  fillAndStroke(COL.standBlue, COL.outline, strokeW);

  // Horizontal Clamp Arm extending from Rod to Flask Neck
  roundedRectPath(flaskCX - 48 * s, clampY, (rodCX + rodW * 0.5) - (flaskCX - 48 * s), clampH, 8 * s);
  fillAndStroke(COL.standBlueLight, COL.outline, strokeW);

  // Mechanical Clamp Joint Block on Vertical Rod
  roundedRectPath(rodCX - 18 * s, clampY - 8 * s, 36 * s, clampH + 16 * s, 8 * s);
  fillAndStroke(COL.standBlueDark, COL.outline, strokeW);

  // 5B. Heavy Blue Laboratory Stand Base (Sitting flush on baseLineY)
  roundedRectPath(standBaseX, standBaseY, standBaseW, standBaseH, 22 * s);
  fillAndStroke(COL.standBlue, COL.outline, strokeW);

  // Base bottom darker bevel strip
  roundedRectPath(standBaseX + 12 * s, standBaseY + standBaseH - 16 * s, standBaseW - 24 * s, 10 * s, 5 * s);
  fillAndStroke(COL.standBlueDark, null, 0);

  // 5C. Laboratory Burner Dome & Crisp Layered Flat Vector Flame
  // Burner sits on top of standBaseY at flaskCX; Flask bottom is at cy + 190*s -> 146*s vertical space!
  const burnerW = 148 * s;
  const burnerH = 42 * s;
  const burnerY = standBaseY - burnerH * 0.65;

  // Burner Dome
  ctx.beginPath();
  ctx.moveTo(flaskCX - burnerW * 0.5, standBaseY);
  ctx.quadraticCurveTo(flaskCX - burnerW * 0.45, burnerY, flaskCX, burnerY);
  ctx.quadraticCurveTo(flaskCX + burnerW * 0.45, burnerY, flaskCX + burnerW * 0.5, standBaseY);
  ctx.closePath();
  fillAndStroke(COL.standBlueDark, COL.outline, strokeW);

  // Burner Nozzle Collar
  roundedRectPath(flaskCX - 28 * s, burnerY - 14 * s, 56 * s, 18 * s, 6 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  // Crisp Flat Vector Flame (Strictly between y = burnerY - 14*s and y = cy + 205*s, never touching flask!)
  const flameBaseY = burnerY - 14 * s;
  const flameHeight = (74 + Math.sin(p6) * 8) * s;
  const flameTipY = flameBaseY - flameHeight;
  const flameSwayX = Math.sin(p4) * 5 * s;
  const flameHalfW = (30 + Math.cos(p6) * 2.5) * s;

  // Outer Flame (Vibrant Orange-Coral)
  ctx.beginPath();
  ctx.moveTo(flaskCX, flameBaseY);
  ctx.bezierCurveTo(
    flaskCX - flameHalfW * 1.15, flameBaseY - flameHeight * 0.22,
    flaskCX - flameHalfW * 0.85, flameBaseY - flameHeight * 0.68,
    flaskCX + flameSwayX, flameTipY
  );
  ctx.bezierCurveTo(
    flaskCX + flameHalfW * 0.85, flameBaseY - flameHeight * 0.68,
    flaskCX + flameHalfW * 1.15, flameBaseY - flameHeight * 0.22,
    flaskCX, flameBaseY
  );
  ctx.closePath();
  fillAndStroke(COL.orangeMid, COL.outline, strokeW);

  // Inner Flame Core (Warm Gold-Yellow)
  const coreHeight = flameHeight * 0.58;
  const coreHalfW = flameHalfW * 0.55;
  ctx.beginPath();
  ctx.moveTo(flaskCX, flameBaseY - 2 * s);
  ctx.bezierCurveTo(
    flaskCX - coreHalfW, flameBaseY - coreHeight * 0.25,
    flaskCX - coreHalfW * 0.75, flameBaseY - coreHeight * 0.72,
    flaskCX + flameSwayX * 0.6, flameBaseY - coreHeight
  );
  ctx.bezierCurveTo(
    flaskCX + coreHalfW * 0.75, flameBaseY - coreHeight * 0.72,
    flaskCX + coreHalfW, flameBaseY - coreHeight * 0.25,
    flaskCX, flameBaseY - 2 * s
  );
  ctx.closePath();
  fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

  // 5D. Central Conical Erlenmeyer Flask (Neck Top: cy - 235*s, Base Bottom: cy + 188*s)
  const neckTopY = cy - 235 * s;
  const neckBotY = cy - 115 * s;
  const flaskBotY = cy + 188 * s;
  const neckHalfW = 38 * s;
  const bodyHalfW = 136 * s;
  const cornerR = 32 * s;

  function defineErlenmeyerPath() {
    ctx.beginPath();
    ctx.moveTo(flaskCX - neckHalfW, neckTopY);
    ctx.lineTo(flaskCX - neckHalfW, neckBotY);
    ctx.lineTo(flaskCX - bodyHalfW, flaskBotY - cornerR);
    ctx.quadraticCurveTo(flaskCX - bodyHalfW, flaskBotY, flaskCX - bodyHalfW + cornerR, flaskBotY);
    ctx.lineTo(flaskCX + bodyHalfW - cornerR, flaskBotY);
    ctx.quadraticCurveTo(flaskCX + bodyHalfW, flaskBotY, flaskCX + bodyHalfW, flaskBotY - cornerR);
    ctx.lineTo(flaskCX + neckHalfW, neckBotY);
    ctx.lineTo(flaskCX + neckHalfW, neckTopY);
    ctx.closePath();
  }

  // Flask Glass Background Fill
  defineErlenmeyerPath();
  fillAndStroke(COL.glassTint, null, 0);

  // Golden Liquid Wave inside Erlenmeyer Flask
  const flaskLiquidY = cy + 32 * s + Math.sin(p2) * 10 * s;
  drawClippedWaveLiquid(
